     }

     #[verifier::opaque]
     pub open spec fn bytes(&self, segment_id: SegmentId) -> Set<int> {
         let start = segment_start(segment_id);
         self@.map_flatten_by(
             |i: int| Set::range(start + i * COMMIT_SIZE, start + (i + 1) * COMMIT_SIZE),
             |addr: int| (addr - start) / COMMIT_SIZE as int,
         )
     }

